  byte[] record=Encoding.UTF8.GetBytes("0000"+Common.Json.Serialize(new{wpId=id,wpName=md5+ext,wpMd5=md5,wpType=video?1:2}));for(int i=0;i<record.Length;i++)record[i]^=0xe7;string rp=Path.Combine(fixtureRoot,"cache_info",id+"_fixture.dat");File.WriteAllBytes(rp,record);return LocalImport.ReadRecord(rp);
