  int shows=0,stops=0,exits=0;var pending=new TaskCompletionSource<bool>();var commands=new TrayCommands(()=>{shows++;return true;},()=>{stops++;return pending.Task;},()=>exits++);commands.Open(active);commands.Open(active);var first=commands.Stop(active);var second=commands.Stop(active);Need(shows==2&&stops==1&&second.IsCompleted,"tray-commands-use-existing-window-and-coalesce-stop");pending.SetResult(true);first.GetAwaiter().GetResult();commands.Exit(closing);commands.Exit(active);Need(exits==1,"tray-exit-routes-once-through-close-guard");
 }
